    public boolean canBecome(ClaimStatus next) {
        return switch (this) {
            case DRAFT -> Set.of(OPEN, VOID).contains(next);
            case OPEN -> Set.of(SETTLED, VOID).contains(next);
            case SETTLED, VOID -> false;
        };
    }
}
